func TestParseInt(t *testing.T) {
	if got, err := parseInt([]byte{49, 50, 51}); err != nil || got != 123 {
		t.Errorf("parseInt([]byte{49, 50, 51}) = %d, %v, want 123", got, err)
	}
	if got, err := parseInt([]byte{45, 55}); err != nil || got != -7 {
		t.Errorf("parseInt([]byte{45, 55}) = %d, %v, want -7", got, err)
	}
	if _, err := parseInt([]byte{}); !errors.Is(err, ErrEmpty) {
		t.Errorf("parseInt([]byte{}) error = %v, want ErrEmpty", err)
	}
	if _, err := parseInt([]byte{45}); !errors.Is(err, ErrLoneMinus) {
		t.Errorf("parseInt([]byte{45}) error = %v, want ErrLoneMinus", err)
	}
	if _, err := parseInt([]byte{49, 120}); !errors.Is(err, ErrNotDigit) {
		t.Errorf("parseInt([]byte{49, 120}) error = %v, want ErrNotDigit", err)
	}
}
